// Conformance harness consuming the shared libphext 0.6 chain fixtures in
// tests/fixtures/chains/ (see FIXTURES.md in the ports program workspace;
// the set was generated by calling libphext-rs 0.6.0 itself).
// For every case: parse input.phext with parse_chains, check the chain /
// member / scroll structure recorded in expected.tsv, check every recorded
// fetch against Chain::fetch byte-for-byte, and require
// serialize_chains(parse_chains(input)) to be byte-identical to the input.
// Mirrors libphext-rs tests/chain_fixtures.rs.
#include "../phext.h"

#include <cstdio>
#include <fstream>
#include <map>
#include <sstream>
#include <string>
#include <utility>
#include <vector>

static int checks = 0;
static int failures = 0;
static std::string current_case;

static std::string escape_bytes(const std::string& s) {
   std::string out;
   char buf[8];
   for (char raw : s) {
      const unsigned char b = static_cast<unsigned char>(raw);
      if (b >= 0x20 && b < 0x7F) out.push_back(raw);
      else { std::snprintf(buf, sizeof(buf), "\\x%02x", b); out += buf; }
   }
   return out;
}
static void fail(const std::string& what) {
   failures += 1;
   std::printf("  FAIL [%s] %s\n", current_case.c_str(), what.c_str());
}
static void check_eq_str(const std::string& a, const std::string& e, const std::string& what) {
   checks += 1;
   if (a != e) fail(what + ": actual \"" + escape_bytes(a.substr(0, 80)) + "\" (" + std::to_string(a.size()) +
                    " bytes) expected \"" + escape_bytes(e.substr(0, 80)) + "\" (" + std::to_string(e.size()) + " bytes)");
}
static void check_eq_size(std::size_t a, std::size_t e, const std::string& what) {
   checks += 1;
   if (a != e) fail(what + ": actual " + std::to_string(a) + " expected " + std::to_string(e));
}
static void check_eq_bool(bool a, bool e, const std::string& what) {
   checks += 1;
   if (a != e) fail(what + std::string(": actual ") + (a ? "true" : "false") + " expected " + (e ? "true" : "false"));
}

static std::string read_binary(const std::string& path) {
   std::ifstream in(path, std::ios::binary);
   std::stringstream ss;
   ss << in.rdbuf();
   return ss.str();
}
static std::vector<std::string> split_tab(const std::string& line) {
   std::vector<std::string> out;
   std::size_t start = 0;
   for (std::size_t i = 0; i <= line.size(); ++i) {
      if (i == line.size() || line[i] == '\t') { out.push_back(line.substr(start, i - start)); start = i + 1; }
   }
   return out;
}
static std::pair<std::string, std::string> kv(const std::string& field) {
   const std::size_t eq = field.find('=');
   return {field.substr(0, eq), field.substr(eq + 1)};
}

static int total_fetches = 0;

static void run_case(const std::string& root, const std::string& case_name) {
   current_case = case_name;
   const std::string dir = root + "/" + case_name;
   const std::string tsv = read_binary(dir + "/expected.tsv");
   const std::string input = read_binary(dir + "/input.phext");

   std::size_t expected_chains = 0; bool have_chains = false;
   std::map<std::size_t, std::pair<bool, std::size_t>> chain_info;
   std::map<std::pair<std::size_t, std::size_t>, std::pair<std::size_t, std::size_t>> member_info;
   struct Fetch { std::size_t chain; std::string address; std::string file; };
   std::vector<Fetch> fetches;

   std::stringstream lines(tsv);
   std::string line;
   while (std::getline(lines, line)) {
      if (!line.empty() && line.back() == '\r') line.pop_back();
      if (line.empty()) continue;
      const auto f = split_tab(line);
      if (f[0] == "input_bytes") {
         check_eq_size(input.size(), static_cast<std::size_t>(std::stoull(f[1])), "input_bytes");
      } else if (f[0] == "chains") {
         expected_chains = static_cast<std::size_t>(std::stoull(f[1])); have_chains = true;
      } else if (f[0] == "chain") {
         const std::size_t ci = static_cast<std::size_t>(std::stoull(f[1]));
         bool closed = false; std::size_t members = 0;
         for (std::size_t i = 2; i < f.size(); ++i) { const auto p = kv(f[i]); if (p.first == "closed") closed = p.second == "true"; else if (p.first == "members") members = static_cast<std::size_t>(std::stoull(p.second)); }
         chain_info[ci] = {closed, members};
      } else if (f[0] == "member") {
         const std::size_t ci = static_cast<std::size_t>(std::stoull(f[1]));
         const std::size_t mi = static_cast<std::size_t>(std::stoull(f[2]));
         std::size_t bytes = 0, scrolls = 0;
         for (std::size_t i = 3; i < f.size(); ++i) { const auto p = kv(f[i]); if (p.first == "bytes") bytes = static_cast<std::size_t>(std::stoull(p.second)); else if (p.first == "scrolls") scrolls = static_cast<std::size_t>(std::stoull(p.second)); }
         member_info[{ci, mi}] = {bytes, scrolls};
      } else if (f[0] == "fetch") {
         Fetch fetch{0, "", ""};
         for (std::size_t i = 1; i < f.size(); ++i) { const auto p = kv(f[i]); if (p.first == "chain") fetch.chain = static_cast<std::size_t>(std::stoull(p.second)); else if (p.first == "address") fetch.address = p.second; else if (p.first == "file") fetch.file = p.second; }
         fetches.push_back(fetch);
      }
   }

   const auto chains = phext::parse_chains(input);
   checks += 1; if (!have_chains) fail("no chains line in expected.tsv");
   check_eq_size(chains.size(), expected_chains, "chain count");
   for (std::size_t ci = 0; ci < chains.size(); ++ci) {
      const auto it = chain_info.find(ci);
      if (it == chain_info.end()) { checks += 1; fail("missing chain info"); continue; }
      check_eq_bool(chains[ci].closed, it->second.first, "chain closed");
      check_eq_size(chains[ci].members.size(), it->second.second, "member count");
      for (std::size_t mi = 0; mi < chains[ci].members.size(); ++mi) {
         const auto mit = member_info.find({ci, mi});
         if (mit == member_info.end()) { checks += 1; fail("missing member info"); continue; }
         check_eq_size(chains[ci].members[mi].size(), mit->second.first, "member bytes");
         check_eq_size(phext::phokenize(chains[ci].members[mi]).size(), mit->second.second, "member scroll count");
      }
   }
   check_eq_str(phext::serialize_chains(chains), input, "round trip");
   for (const Fetch& fetch : fetches) {
      total_fetches += 1;
      const std::string expected = read_binary(dir + "/" + fetch.file);
      if (fetch.chain >= chains.size()) { checks += 1; fail("fetch chain out of range"); continue; }
      check_eq_str(chains[fetch.chain].fetch(fetch.address), expected, "fetch " + fetch.address);
   }
   std::printf("%s %s (%zu fetches)\n", failures == 0 ? "PASS" : "case-done", case_name.c_str(), fetches.size());
}

int main() {
   const std::string root = "tests/fixtures/chains";
   const std::string index = read_binary(root + "/cases.tsv");
   std::stringstream lines(index);
   std::string line;
   int case_count = 0;
   bool first = true;
   while (std::getline(lines, line)) {
      if (!line.empty() && line.back() == '\r') line.pop_back();
      if (first) { first = false; continue; }
      if (line.empty()) continue;
      const std::string case_name = split_tab(line)[0];
      case_count += 1;
      run_case(root, case_name);
   }
   checks += 1; if (case_count < 10) fail("expected at least 10 fixture cases, got " + std::to_string(case_count));
   checks += 1; if (total_fetches != 42) fail("expected 42 fetches, got " + std::to_string(total_fetches));
   std::printf("test_chain_fixtures: %d cases, %d fetches, %d checks, %d failures\n", case_count, total_fetches, checks, failures);
   return failures > 125 ? 125 : failures;
}
